    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def get(obs, *keys, default=None):
        for k in keys:
            try:
                v = obs.get(k)
            except Exception:
                v = None
            if v is not None:
                return v
        return default

    def is_pos(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float))

    def best_by_distance(src, items, farthest=False):
        best = None
        best_d = None
        if not isinstance(items, (list, tuple)):
            return None
        for it in items:
            p = None
            if is_pos(it):
                p = (it[0], it[1])
            elif isinstance(it, dict):
