    sx, sy = pair(get(observation, "self_position", "position", "self_pos", default=(0, 0)))
    ox, oy = pair(get(observation, "opponent_position", "enemy_position", "opponent_pos", default=(sx, sy)))
    gw = get(observation, "grid_width", "width", default=0) or 0
    gh = get(observation, "grid_height", "height", default=0) or 0

    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if "pursuit" in env or "evasion" in env:
        role = str(get(observation, "self_role", "role", default="pursuer")).lower()
        if "pursuer" in role or "chaser" in role:
            return step_toward(self_pos, opp_pos)

        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        # Move toward the corner farthest from the opponent; if map size unknown, just flee from opponent.
        corner = best_by_distance(opp_pos, corners, farthest=True)
        if corner is not None:
            return step_toward(self_pos, corner)
        return step_away(self_pos, opp_pos)

