            "unclaimed_cells", "neutral_cells", "territory_targets", "frontier_cells",
            "empty_cells", "enemy_territory", "opponent_territory", "capture_points",
            "objectives", "targets"
        ))
        # Prefer the closest contestable cell.
        target = best_by_distance(self_pos, targets, farthest=False)
        if target is not None:
            return step_toward(self_pos, target)

        # If no explicit targets, pressure opponent or drift to center.
        if is_pos(opp_pos):
            return step_toward(self_pos, opp_pos)
        if gw and gh:
            return step_toward(self_pos, (gw // 2, gh // 2))
        return [0, 0]

    # resource_collection and default fallback
    resources = all_targets(observation, (
        "resources", "resource_positions", "resource_cells", "items", "collectibles",
        "mines", "gold", "food"
    ))
    target = best_by_distance(self_pos, resources, farthest=False)
    if target is not None:
        return step_toward(self_pos, target)

    # If no resource list exists, use any visible objective-like cells.
    alt = all_targets(observation, ("targets", "objectives", "unclaimed_cells", "neutral_cells"))
    target = best_by_distance(self_pos, alt, farthest=False)
